const items = $input.all();
const salida = [];

// Campos obligatorios para poder generar la propuesta
const obligatorios = [
  'nombre_estudiante',
  'correo',
  'carnet',
  'carrera',
  'sede',
  'area_interes',
  'descripcion_problema',
  'objetivo_proyecto',
];

// Todos los campos esperados del formulario
const campos = [
  'nombre_estudiante','correo','carnet','carrera','sede','area_interes',
  'linea_investigacion','tipo_problema','descripcion_problema','contexto',
  'poblacion_beneficiada','objetivo_proyecto','recursos_disponibles',
  'alcance_estimado','observaciones',
];

for (const item of items) {
  const b = (item.json && (item.json.body || item.json)) || {};
  const errores = [];

  for (const campo of obligatorios) {
    if (b[campo] === undefined || b[campo] === null || String(b[campo]).trim() === '') {
      errores.push(campo);
    }
  }

  // Validación de formato de correo
  const correo = b.correo ? String(b.correo).trim() : '';
  if (correo && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(correo)) {
    errores.push('correo (formato inválido)');
  }

  const datos = {
    id_formulario: b.id_formulario !== undefined ? Number(b.id_formulario) : null,
    id_estudiante: b.id_estudiante !== undefined ? Number(b.id_estudiante) : null,
  };
  for (const c of campos) {
    datos[c] = b[c] !== undefined && b[c] !== null ? String(b[c]).trim() : '';
  }

  const requestId = 'REQ-' + Date.now() + '-' + Math.random().toString(36).substring(2, 8).toUpperCase();

  salida.push({
    json: {
      valido: errores.length === 0,
      errores,
      request_id: requestId,
      fecha_procesamiento: new Date().toISOString(),
      datos,
    },
  });
}

return salida;

const salida = [];

for (const item of $input.all()) {
  const j = item.json || {};

  let raw = '';

  if (
    j.output &&
    j.output[0] &&
    j.output[0].content &&
    j.output[0].content[0] &&
    j.output[0].content[0].text
  ) {
    raw = j.output[0].content[0].text;
  } else if (j.message && j.message.content) {
    raw = typeof j.message.content === 'string'
      ? j.message.content
      : JSON.stringify(j.message.content);
  } else if (typeof j.content === 'string') {
    raw = j.content;
  } else if (j.content) {
    raw = JSON.stringify(j.content);
  } else if (typeof j.text === 'string') {
    raw = j.text;
  } else if (typeof j.output_text === 'string') {
    raw = j.output_text;
  } else if (j.output_text) {
    raw = JSON.stringify(j.output_text);
  } else {
    raw = JSON.stringify(j);
  }

  if (typeof raw !== 'string') {
    raw = JSON.stringify(raw);
  }

  let parsed = {};
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    const m = typeof raw === 'string' ? raw.match(/\{[\s\S]*\}/) : null;
    if (m) {
      try {
        parsed = JSON.parse(m[0]);
      } catch (e2) {
        parsed = {};
      }
    }
  }

  const toArray = (v) => Array.isArray(v) ? v : (v ? [String(v)] : []);
  const toStr = (v) => (v === undefined || v === null) ? '' : String(v);

  const ctx = $('Construir Prompt IA').item.json;

  salida.push({
    json: {
      request_id: ctx.request_id,
      fecha_procesamiento: ctx.fecha_procesamiento,
      datos: ctx.datos,
      propuestas_tema: toArray(parsed.propuestas_tema),
      planteamiento_problema: toStr(parsed.planteamiento_problema),
      objetivo_general: toStr(parsed.objetivo_general),
      objetivos_especificos: toArray(parsed.objetivos_especificos),
      justificacion: toStr(parsed.justificacion),
      estado: 'procesado',
    },
  });
}

return salida;

