const salida = [];

for (const item of $input.all()) {
  // Recuperar los datos procesados (el item de error de MySQL puede no traerlos)
  const p = $('Procesar Respuesta IA').item.json;

  const registroTemporal = {
    request_id: p.request_id,
    fecha_creacion: p.fecha_procesamiento,
    estado: 'pendiente_persistencia',
    datos: p.datos,
    propuestas: {
      propuestas_tema: p.propuestas_tema,
      planteamiento_problema: p.planteamiento_problema,
      objetivo_general: p.objetivo_general,
      objetivos_especificos: p.objetivos_especificos,
      justificacion: p.justificacion,
    },
  };

  // Log de trazabilidad del almacenamiento temporal
  console.log('ALMACENAMIENTO_TEMPORAL', JSON.stringify(registroTemporal));

  salida.push({ json: registroTemporal });
}

return salida;
